#include<stdio.h>
#include<math.h>
int main()
{
    long long int X, f;
    scanf("%lld",&X);
    if(X%2 == 0)
    {
        f = X/2;
        printf("%lld\n",f);
    }
    else
    { f = (- X - 1)/2 ;
        printf("%lld\n",f);}
    return 0;
}
